eval("{module.exports = /*#__PURE__*/JSON.parse('{\"data\":[{\"id\":1,\"city\":\"ნიუ ჯერსი\",\"month\":\"ივნისი\",\"year\":\"2020\",\"text\":\"მინდა მადლობა გადავუხადო თქვენთვის იმისთვის, რომ მიზანი გაქვთ ადამიანები ბუნებასთან ახლოს მოიყვანოთ! მე და ბავშვებმა ძალიან აღფრთოვანდით ამ შესაძლებლობით, რეალურ დროში წარმოუდგენელი ცხოველების ცხოვრებას გაეცნოთ.\",\"name\":\"კარენ მაითლანი\"},{\"id\":2,\"city\":\"ტორონტო\",\"month\":\"ნოემბერი\",\"year\":\"2020\",\"text\":\"ჩვენ ვისიამოვნეთ მსოფლიოს სხვადასხვა ადგილიდან ცხოველების მუდმივი არჩევანით. გმადლობთ, რომ ჩვენთან ერთად საინტერესო ცხოველების მეგობრებს გაზიარებთ, რათა მათგან ვისწავლოთ და გავაღრმავოთ ცხოველთა სამეფოს ცოდნა.\",\"name\":\"კაროლ ლარსენი\"},{\"id\":3,\"city\":\"ლონდონი\",\"month\":\"თებერვალი\",\"year\":\"2020\",\"text\":\"საუკეთესო გამოცდილება ბავშვებისთვის და მოზრდილებისთვის! თუ ვინმეს უნდა ატრაქციონი, რომელიც ასწავლის ადამიანებს ველური ცხოველების შესახებ – ეს თქვენთვისაა! ძალიან გირჩევთ თავად ნახოთ ეკრანზე ცხოველების მრავალფეროვნება.\",\"name\":\"C. სტოკმანი\"},{\"id\":4,\"city\":\"ამსტერდამი\",\"month\":\"ივნისი\",\"year\":\"2020\",\"text\":\"მინდა მადლობა გადავუხადო საოცარი ადგილების ჩვენებისთვის ჩვენებით, სადაც კამერების საშუალებით ყველაფერი შეგვიძლია ვნახოთ, რასაც ალბათ თავად ვერ ვნახავდით. Zoo Online-ს ბევრი დადებითი მხარე აქვს და მადლიერი ვარ ამისთვის. ძალიან დიდი მადლობა!\",\"name\":\"ტომას რეი\"},{\"id\":5,\"city\":\"სიდნეი\",\"month\":\"მარტი\",\"year\":\"2021\",\"text\":\"რა საოცარი პლატფორმაა! ჩემი ოჯახი ყოველ შაბათ-კვირას პირდაპირი სერებით უყურებს. ეს არის საგანმანათლებლო და სახალისო ერთდროულად. ბავშვები სწავლობენ ბუნების დაცვის შესახებ.\",\"name\":\"ემმა ვილსონი\"},{\"id\":6,\"city\":\"ბერლინი\",\"month\":\"აგვისტო\",\"year\":\"2021\",\"text\":\"ბიოლოგიის მასწავლებლად, მე რეგულარულად ვიყენებ Zoo Online-ს ჩემს კლასში. პირდაპირი სერების საშუალებით მიღებული გამოცდილება წიგნებით ვერ შედარებულა. მადლობა ამ შესანიშნავი რესურსისთვის!\",\"name\":\"ჰანს მულერი\"},{\"id\":7,\"city\":\"ტოკიო\",\"month\":\"დეკემბერი\",\"year\":\"2021\",\"text\":\"კამერების ხარისხი და ცხოველების მრავალფეროვნება შესანიშნავია. განსაკუთრებით მიყვარს პანდა კამერა. ეს ყოველ დღე მიხარია. გააგრძელეთ შესანიშნავი მუშაობა!\",\"name\":\"იუკი ტანაკა\"},{\"id\":8,\"city\":\"პარიზი\",\"month\":\"იანვარი\",\"year\":\"2022\",\"text\":\"ეს სწორედ ისაა, რაც მსოფლიო ახლა საჭიროებს – საშუალება ბუნებასთან სახლში ურთიერთობისთვის. პირდაპირი სერები სიმშვიდეს და შთაგონებას განიჭებს. Zoo Online-ს ყველა მეგობარს და კოლეგას შევთავაზე.\",\"name\":\"სოფი დუბუა\"},{\"id\":9,\"city\":\"ვენკუვერი\",\"month\":\"აპრილი\",\"year\":\"2022\",\"text\":\"ჩემი ბებია ყოველდღე უყურებს ცხოველებს. ეს მისი ყოველდღიური რუტინის ნაწილი გახდა და ბედნიერებას უქმნის. მადლობა ასეთი რაღაც შექმნისთვის, რაც თაობებს ერთდროულად აკავშირებს!\",\"name\":\"მაიკლ ჩენი\"},{\"id\":10,\"city\":\"მადრიდი\",\"month\":\"ივლისი\",\"year\":\"2022\",\"text\":\"Zoo Online-ის შინაარსობრივი მესიჯი ბუნების დაცვის შესახებ ძალიან ძლიერია. არა მხოლოდ ვნახავთ საოცარ ცხოველებს, არამედ ვსწავლობთ მათი გარემოებისა და პრობლემების შესახებ. ეს საუკეთესო განათლებაა!\",\"name\":\"იზაბელა როდრიგესი\"},{\"id\":11,\"city\":\"მელბურნი\",\"month\":\"სექტემბერი\",\"year\":\"2022\",\"text\":\"ყოველთვის გაოგნებული ვარ ცხოველების ქცევებით, რასაც თქვენს პლატფორმაზე ვხედავ. თამაშისმიერი ზღვის ხორციდან დაწყებული, მეფე ლომებამდე, თითოეული მომენტი ძვირფასია. მადლობა, რომ ყველა ადამიანი ცხოველებს წვდომას აძლევთ!\",\"name\":\"ჯეიმს ფოსტერი\"},{\"id\":12,\"city\":\"სტოკჰოლმი\",\"month\":\"ოქტომბერი\",\"year\":\"2022\",\"text\":\"როგორც ადამიანი, ვინც ჯანმრთელობის პრობლემების გამო ვერ ვმოგზაურობს, Zoo Online ახალი სამყაროს დამთვალიერებელი გახადა ჩემთვის. თავს ბუნებასთან დაკავშირებულად ვგრძნობ გზებით, რაც არასდროს მეგონა შესაძლებელი. მართლა მადლობელი ვარ!\",\"name\":\"ლარს ანდერსონი\"},{\"id\":13,\"city\":\"ჩიკაგო\",\"month\":\"თებერვალი\",\"year\":\"2023\",\"text\":\"ჩემი ვაჟი ბებერების კამერით აღფრთოვანდა! ეს გაიზარდა მისი ინტერესი ველური ცხოველების ბიოლოგიაში და ახლა ამბობს, რომ ზოოლოგი გახდება. მადლობა მომავალი თაობის შთაგონებისთვის!\",\"name\":\"პატრიცია ბრაუნი\"},{\"id\":14,\"city\":\"სინგაპური\",\"month\":\"მაისი\",\"year\":\"2023\",\"text\":\"თქვენი კამერების განლაგების დეტალებზე ყურადღება შთამბეჭდავია. თითოეული კუთხე ისტორია fortæს. Zoo Online-დან უფრო ბევრი რამ გავიგე ცხოველების ქცევის შესახებ ვიდრე ნებისმიერი დოკუმენტური ფილმიდან.\",\"name\":\"ვეი ჟანგი\"},{\"id\":15,\"city\":\"დუბლინი\",\"month\":\"ივნისი\",\"year\":\"2023\",\"text\":\"რა საოცარი კონცეფცია! პირდაპირი ურთიერთობა მაბედნიერებს ისე, თითქოს იქ ვიქნები. ჩემი ფავორიტი სპექტაკლი არის სპილოების კვების დროს დაკვირვება. აბსოლუტურად მონუსხველი!\",\"name\":\"კონნორი ო\\'ბრაიენი\"},{\"id\":16,\"city\":\"ლოს ანჯელესი\",\"month\":\"აგვისტო\",\"year\":\"2023\",\"text\":\"მუშაობ სახლში და Zoo Online-ს მეორე მონიტორზე ვაკონტროლებ. ეს დამშვიდებას აძლევს და ბუნებასთან სიახლოვეს განვიცდი. საუკეთესო ფონური ყურება!\",\"name\":\"ჯესიკა მარტინესი\"},{\"id\":17,\"city\":\"ოსლო\",\"month\":\"ნოემბერი\",\"year\":\"2023\",\"text\":\"არქტიკული ზანგის კამერა ჩემი აბსოლუტური ფავორიტია! მათი ბუნებრივ გარემოში ყურება სუნთქვას გართმევს. Zoo Online ჩემი ყოველდღიური გაქცევის ადგილია ქალაქის ხმაურიანი ცხოვრებისგან.\",\"name\":\"ინგრიდ იოჰანსენი\"},{\"id\":18,\"city\":\"კეიპ ტაუნი\",\"month\":\"იანვარი\",\"year\":\"2024\",\"text\":\"აფრიკაში მცხოვრები, მე ვაფასებ, როგორ აჩვენებს Zoo Online ჩვენს ველურ ბუნებას მსოფლიოში. მნიშვნელოვანია თქვენი შრომა კონსერვაციის ცნობიერების ამაღლებისთვის. გააგრძელეთ!\",\"name\":\"თაბო ნდლოვუ\"},{\"id\":19,\"city\":\"ბოსტონი\",\"month\":\"მარტი\",\"year\":\"2024\",\"text\":\"ჩემი თერაპიული სესიები ახლა მოიცავს Zoo Online-ის ყურებას ჩემს პაციენტებთან ერთად. ცხოველების ბუნებრივი მდგომარეობის დაკვირვების დამამშვიდებელი ეფექტი სამკურნალოა. მადლობა ამ სამკურნალო რესურსისთვის!\",\"name\":\"დოქტორ სარა მიტჩელი\"},{\"id\":20,\"city\":\"სეული\",\"month\":\"მაისი\",\"year\":\"2024\",\"text\":\"Zoo Online-ს საგანმანათლებლო მნიშვნელობა უზარმაზარია. მე ვსწავლობ მას ჩემი ბავშვების სახლში სწავლების პროგრამაში. ისინი სწავლობენ ეკოსისტემებს, ცხოველების ქცევას და ბუნების დაცვის მცდელობებს.\",\"name\":\"მინ-ჯი კიმი\"},{\"id\":21,\"city\":\"რომი\",\"month\":\"ივლისი\",\"year\":\"2024\",\"text\":\"მე ველურ ბუნებაში ფოტოგრაფი ვარ და ვიყენებ Zoo Online-ს რეფერენციისა და შთაგონების მიზნით. კამერით გადაღებული ბუნებრივი ქცევები უპრეცედენტოა. ეს ძვირფასია ყველასთვის, ვისაც ბუნება უყვარს!\",\"name\":\"მარკო როსი\"},{\"id\":22,\"city\":\"ოკლენდ\",\"month\":\"სექტემბერი\",\"year\":\"2024\",\"text\":\"Zoo Online ჩვენს ოჯახს უფრო ახლოს მოუკრავს. გვაქვს ყოველკვირეული ცხოველების ყურების შეხვედრები, სადაც სხვადასხვა ცხოველს ვუყურებთ. ეს საყვარელი ტრადიცია გახდა. მადლობა ასეთი მოგონებების შექმნისთვის!\",\"name\":\"რაჩელ ტომპსონი\"},{\"id\":23,\"city\":\"მონტრეალი\",\"month\":\"ნოემბერი\",\"year\":\"2024\",\"text\":\"პოლარული დათვების კამერა აბსოლუტურად საოცარია! მათი ყურება არქტიკაში ლამაზია და გონებას ავითარებს კლიმატის ცვლილების შესახებ. საგანმანათლებლო და ემოციურად მოსაწონი.\",\"name\":\"პიერ ლებლანი\"},{\"id\":24,\"city\":\"მუმბაი\",\"month\":\"დეკემბერი\",\"year\":\"2025\",\"text\":\"როგორც ცხოველთა უფლებების დამცველი, ვაფასებ, რომ Zoo Online ეთიკურ ველურ ბუნებაზე დაკვირვებას წარმართავს. ეს სრულყოფილი მაგალითია, როგორ შეიძლება ტექნოლოგიამ ემპათია და გაგება გააღვივოს.\",\"name\":\"პრია შარმა\"}]}');\n\n//# sourceURL=webpack://online-zoo/./local/feedback-ka.json?\n}");

